import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"What are pages","description":"Pages and Portals in ApptiveGrid — interfaces built from Blocks.","frontmatter":{"title":"What are pages","description":"Pages and Portals in ApptiveGrid — interfaces built from Blocks."},"headers":[],"relativePath":"en/seiten/was-sind-seiten.md","filePath":"en/seiten/was-sind-seiten.md","lastUpdated":1787319236000}'),r={name:"en/seiten/was-sind-seiten.md"};function i(n,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-are-pages" tabindex="-1">What are pages <a class="header-anchor" href="#what-are-pages" aria-label="Permalink to &quot;What are pages&quot;">​</a></h1><p>A <strong>Page</strong> is a freely composed interface. You build it out of <strong>Blocks</strong>: headings, text paragraphs, images, input fields, embedded views, evaluations, and layout containers.</p><p>Publishing a Page creates a <strong>Portal</strong> — an independent web address you can share or embed in your own website.</p><p>The empty state in the Pages area describes it like this:</p><blockquote><p><em>Welcome to your &quot;Pages&quot; area. Here you can keep all your information, notes, and documentation.</em></p></blockquote><p>But that only covers the simplest case. Pages can do a lot more.</p><h2 id="what-pages-are-good-for" tabindex="-1">What Pages are good for <a class="header-anchor" href="#what-pages-are-good-for" aria-label="Permalink to &quot;What Pages are good for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use</th><th>What you need for it</th></tr></thead><tbody><tr><td>Internal documentation, notes, manuals</td><td>Text and heading blocks</td></tr><tr><td>Dashboard with metrics</td><td>Counter, sum card, donut chart</td></tr><tr><td>Customer portal with a data overview</td><td>Embedded Grid view</td></tr><tr><td>Custom-built data entry screen</td><td>Form field blocks</td></tr><tr><td>Landing page for a process</td><td>Button or QR code block linking to a Flow</td></tr><tr><td>Interface within a Flow</td><td>A Page that a Flow step displays</td></tr></tbody></table><h2 id="page-form-or-view" tabindex="-1">Page, form, or view? <a class="header-anchor" href="#page-form-or-view" aria-label="Permalink to &quot;Page, form, or view?&quot;">​</a></h2><p>Three tools that overlap. The rule of thumb:</p><table tabindex="0"><thead><tr><th>You want to …</th><th>Use</th></tr></thead><tbody><tr><td>Collect data, quickly and without design effort</td><td><a href="/en/formulare/formular-erstellen">Form</a></td></tr><tr><td>Display and edit data, in a table</td><td><a href="/en/ansichten/was-ist-eine-ansicht">View</a></td></tr><tr><td>Combine several things: text, data, input, evaluation</td><td><strong>Page</strong></td></tr><tr><td>An interface with its own structure and layout</td><td><strong>Page</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">A Page can replace a form</p><p>Pages have the same input fields as forms — plus layout, text, images, and embedded data. When a form hits its design limits, a Page is the next step.</p><p>For simple data collection, a form is still faster: pick fields, share, done.</p></div><h2 id="pages-and-blocks" tabindex="-1">Pages and Blocks <a class="header-anchor" href="#pages-and-blocks" aria-label="Permalink to &quot;Pages and Blocks&quot;">​</a></h2><p>A Page is a <strong>tree of Blocks</strong>. Blocks can contain other Blocks — a Layout block arranges the Blocks it contains side by side or stacked, and a Tab layout shows sub-pages as tabs.</p><p>The Block picker is grouped into three categories:</p><ul><li><strong>Basic Blocks</strong> — Paragraph, Headings, Image, Sub-page, Layouts</li><li><strong>Special Blocks</strong> — embedded views, evaluations, buttons, HTML</li><li><strong>Form field Blocks</strong> — all input fields</li></ul><p>→ <a href="/en/seiten/bloecke">Block overview</a> · <a href="/en/referenz/blocktypen">Block types reference</a></p><h2 id="sub-pages" tabindex="-1">Sub-pages <a class="header-anchor" href="#sub-pages" aria-label="Permalink to &quot;Sub-pages&quot;">​</a></h2><p>A Page can contain <strong>sub-pages</strong>. That&#39;s how you build multi-level structures — a manual with chapters, a Portal with several sections.</p><p>Two Layout blocks display sub-pages in particular:</p><ul><li><strong>Tab layout</strong> — <em>Show sub-pages as tabs</em></li><li><strong>Stepper layout</strong> — <em>Show sub-pages as steps</em></li></ul><p>The Stepper layout is suited to guided processes: users work through it step by step.</p><h2 id="the-two-modes-of-a-page" tabindex="-1">The two modes of a Page <a class="header-anchor" href="#the-two-modes-of-a-page" aria-label="Permalink to &quot;The two modes of a Page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Editor</strong></td><td>Editing. You see block frames and controls.</td></tr><tr><td><strong>Application</strong></td><td>Preview. You see the Page as visitors see it.</td></tr></tbody></table><p><em>Back to editing</em> takes you back from the preview.</p><div class="warning custom-block"><p class="custom-block-title">&quot;Page&quot; has three meanings</p><p>Watch closely when reading the interface which one it means:</p><ol><li><strong>Page (Portal)</strong> — what this chapter is about.</li><li><strong>Form page</strong> — a section within a multi-page <a href="/en/formulare/mehrseitige-formulare">form</a>.</li><li><strong>Flow page</strong> — a Page displayed by a <a href="/en/flows/seiten-in-flows">Flow</a>. Technically this is a Page in the sense of 1, embedded in a workflow.</li></ol><p>Two Flow steps are also both called <em>Show page</em> — one is a trigger, one is an action.</p></div><h2 id="from-draft-to-portal" tabindex="-1">From draft to Portal <a class="header-anchor" href="#from-draft-to-portal" aria-label="Permalink to &quot;From draft to Portal&quot;">​</a></h2><p>A Page is initially only visible internally. Only <strong>Create portal link</strong> makes it reachable from outside.</p><p>That&#39;s also true for the preview: if you want to view the Page as a Portal, ApptiveGrid asks:</p><blockquote><p><em>Viewing this preview as a Portal requires a published Portal link. Would you like to create one now?</em></p></blockquote><p>→ <a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></p><h2 id="where-pages-live" tabindex="-1">Where Pages live <a class="header-anchor" href="#where-pages-live" aria-label="Permalink to &quot;Where Pages live&quot;">​</a></h2><p>Pages belong to a <strong>Space</strong> and appear in the sidebar under <strong>Pages</strong>. Whether this area sits above or below the Grids is set in the <a href="/en/spaces/navigation">Space settings</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/seite-erstellen">Creating and editing a page</a></li><li><a href="/en/seiten/bloecke">Block overview</a></li><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></li></ul>',35)])])}const u=t(r,[["render",i]]);export{c as __pageData,u as default};
